import org.traccar.model.Position;
import org.traccar.protocol.Gt06ProtocolDecoder;
import org.traccar.protocol.Protocol;
import org.junit.Assert;
import org.junit.Test;
import java.time.ZoneId;
import io.netty.buffer.Unpooled;
import io.netty.buffer.ByteBuf;
import java.net.SocketAddress;
import java.nio.charset.StandardCharsets;
import java.util.TimeZone;
import org.mockito.Mockito;

public class Gt06ProtocolDecoderTest {

    @Test
    public void decodeGpsBasicTest() {
        ByteBuf buf = Unpooled.copiedBuffer("0800", StandardCharsets.US_ASCII);
        Position position = new Position();
        boolean result = Gt06ProtocolDecoder.decodeGps(position, buf, true, TimeZone.getTimeZone(ZoneId.systemDefault()));
        Assert.assertTrue(result);
    }

    @Test
    public void decodeGpsWithParametersTest() {
        ByteBuf buf = Unpooled.copiedBuffer("0104", StandardCharsets.US_ASCII);
        Position position = new Position();
        boolean result = Gt06ProtocolDecoder.decodeGps(position, buf, false, true, true, TimeZone.getTimeZone(ZoneId.systemDefault()));
        Assert.assertTrue(result);
    }

    @Test
    public void decodeTest() throws Exception {
        ByteBuf buf = Unpooled.copiedBuffer("0200", StandardCharsets.US_ASCII);
        SocketAddress remoteAddress = Mockito.mock(SocketAddress.class);
        Protocol protocol = new Protocol();
        Gt06ProtocolDecoder decoder = new Gt06ProtocolDecoder(protocol);
        Object result = decoder.decode(null, remoteAddress, buf);
        Assert.assertNotNull(result);
    }

    @Test(expected = Exception.class)
    public void decodeExceptionTest() throws Exception {
        ByteBuf buf = Unpooled.copiedBuffer("0300", StandardCharsets.US_ASCII);
        SocketAddress remoteAddress = Mockito.mock(SocketAddress.class);
        Protocol protocol = new Protocol();
        Gt06ProtocolDecoder decoder = new Gt06ProtocolDecoder(protocol);
        decoder.decode(null, remoteAddress, buf);
    }
}
